function go(page){if(typeof window.navigate==='function')window.navigate(page);else $(`.nav-item[data-page="${page}"]`)?.click()}
function toast(title,msg,type='info'){if(typeof window.toast==='function'){try{return window.toast(title,msg,type)}catch(e){}}let n=$('#v36Toast');if(!n){n=document.createElement('div');n.id='v36Toast';n.style.cssText='position:fixed;right:18px;bottom:18px;z-index:2400;max-width:380px;background:#07101f;color:#fff;border-radius:10px;padding:12px 14px;font:11px system-ui;box-shadow:0 16px 40px rgba(0,0,0,.22);transition:.2s';document.body.appendChild(n)}n.innerHTML=`<strong style="display:block;font-size:12px">${esc(title)}</strong><span style="display:block;color:#cbd5e1;margin-top:3px">${esc(msg)}</span>`;n.style.opacity='1';clearTimeout(n._t);n._t=setTimeout(()=>n.style.opacity='0',2700)}
function modal36({eyebrow='',title='',subtitle='',body='',footer='',wide=false}){let b=$('#v36ModalBackdrop'),m=$('#v36Modal');if(!b){b=document.createElement('div');b.id='v36ModalBackdrop';b.className='v34-modal-backdrop';document.body.appendChild(b)}if(!m){m=document.createElement('section');m.id='v36Modal';m.className='v34-modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');document.body.appendChild(m)}const close=()=>{b.classList.remove('show');m.classList.remove('show');document.body.style.overflow=''};b.onclick=close;m.style.maxWidth=wide?'1180px':'';m.innerHTML=`<header class="v34-modal-head"><div><div class="v36-kicker">${eyebrow}</div><h2>${title}</h2><p>${subtitle}</p></div><button class="v34-modal-close" type="button" aria-label="Close">×</button></header><div class="v34-modal-body">${body}</div>${footer?`<footer class="v34-modal-foot">${footer}</footer>`:''}`;$('.v34-modal-close',m).onclick=close;b.classList.add('show');m.classList.add('show');document.body.style.overflow='hidden';m._close=close;return m}

