const issuerBrand={AFDS:'African Distillers',ARTD:'ART',ARIS:'Ariston',BAT:'BAT',CAFCA:'CAFCA',CBZ:'CBZ',CFI:'CFI',COTT:'Cottco',DZL:'Dairibord',DLTA:'Delta',EHZL:'EcoCash',FBC:'FBC',FIDL:'Fidelity Life',FML:'First Mutual',FMP:'First Mutual Properties',GBH:'General Beltings',HIPO:'Hippo Valley',HCCL:'Hwange',MASH:'Mash Holdings',MSHL:'Masimba',MMDZ:'MedTech',MEIK:'Meikles',NPKZ:'Nampak',NTS:'NTS',NMB:'NMB',OKZ:'OK Zimbabwe',PPC:'PPC',PROL:'Proplastics',RTG:'RTG',RIOZ:'RioZim',SACL:'Starafrica',TANG:'Tanganda',TRUW:'Truworths',TSL:'TSL',TURN:'Turnall',UNIF:'Unifreight',WILD:'Willdale',ZBFH:'ZB',ZECO:'Zeco',ZSEH:'ZSE',ZIMP:'Zimpapers',ZIMR:'Zimre',CSAG:'Cass Saddle',DMCS:'Datvest',MIZ:'Made in Zimbabwe',MCMS:'Morgan & Co',REV:'Revitus',TIG:'Tigere',ASUN:'African Sun',AXIA:'Axia',BIND:'Bindura Nickel',CMCL:'Caledonia',EDGR:'Edgars',FCA:'First Capital',INN:'Innscor',NED:'Nedbank',PHL:'Padenga',SCIL:'Seed Co',SIM:'Simbisa',WESTP:'WestProp',ZIMW:'Zimplow',INV:'Invictus',KAV:'Kavango',INFR:'Econet InfraCo',OMU:'Old Mutual',EAGLE:'Eagle REIT',PFUMA:'Pfuma REIT',FMWG:'First Mutual Wealth',KMH:'Karo Mining'};
function currentTicker36(){const t=$('#page-orders .v33-security-head h2')?.textContent?.split('·')[0]?.trim()||'DLTA';return t.replace(/\.(ZW|VX)$/,'')}
function currentPrice36(){return parseFloat(($('#page-orders .v33-price strong')?.textContent||'0').replace(/[^0-9.]/g,''))||10}
function currentCurrency36(){return ($('#page-orders .v33-price strong')?.textContent||'ZWG').trim().split(/\s+/)[0]||'ZWG'}
function orderRange36(){return $('#page-orders [data-v33-range].active')?.dataset?.v33Range||'3M'}
function candles36(ticker,range,last){const n=range==='1M'?26:range==='1Y'?78:52,seed=hash(`${ticker}-${range}`);let close=last*(.92+(seed%11)/100),rows=[];for(let i=0;i<n;i++){const cyc=Math.sin((i+seed%17)*.43)*.006,drift=((i>n*.45)?0.00115:-.00018),noise=((hash(ticker+i)%100)-50)/15500;const open=close*(1+(((hash(i+ticker)%100)-50)/22000));close=Math.max(.01,open*(1+cyc+drift+noise));const wick=(.004+((hash('w'+i+ticker)%90)/10000))*close;const high=Math.max(open,close)+wick,low=Math.max(.001,Math.min(open,close)-wick*.82),vol=35000+(hash(ticker+i*11)%850000);rows.push({open,high,low,close,vol})}const scale=last/rows.at(-1).close;rows=rows.map(r=>({open:r.open*scale,high:r.high*scale,low:r.low*scale,close:r.close*scale,vol:r.vol}));return rows}
function avg36(rows,idx,n,key='close'){if(idx<n-1)return null;let s=0;for(let i=idx-n+1;i<=idx;i++)s+=rows[i][key];return s/n}
function ema36(rows,n){const k=2/(n+1),out=[];let e=rows[0].close;for(let i=0;i<rows.length;i++){e=i===0?rows[i].close:rows[i].close*k+e*(1-k);out.push(e)}return out}
function tvChartSvg36(ticker,range,last,currency){const rows=candles36(ticker,range,last),W=980,H=390,L=16,R=70,T=18,B=46,VH=66,plotH=H-B-VH,plotW=W-L-R,min=Math.min(...rows.map(r=>r.low))*.992,max=Math.max(...rows.map(r=>r.high))*1.008,maxV=Math.max(...rows.map(r=>r.vol)),x=i=>L+plotW*(i+.5)/rows.length,y=v=>T+(plotH-T)*(1-(v-min)/(max-min)),candleW=Math.max(2.4,Math.min(10,plotW/rows.length*.62)),volY=v=>H-B-(VH-12)*(v/maxV);let s=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${esc(ticker)} candlestick price chart with volume, moving average and EMA">`;
 for(let i=0;i<=5;i++){const yy=T+(plotH-T)*i/5,val=max-(max-min)*i/5;s+=`<line class="v36-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text x="${W-R+8}" y="${yy+3}">${currency} ${val.toFixed(currency==='USD'?2:1)}</text>`}
 const labels=range==='1M'?['1M ago','3W','2W','1W','Today']:range==='1Y'?['1Y ago','9M','6M','3M','Today']:['3M ago','10W','6W','2W','Today'];labels.forEach((lab,i)=>{const xx=L+plotW*i/(labels.length-1);s+=`<line class="v36-grid" x1="${xx}" x2="${xx}" y1="${T}" y2="${H-B}"/><text x="${xx}" y="${H-14}" text-anchor="${i===0?'start':i===labels.length-1?'end':'middle'}">${lab}</text>`});
 const ema=ema36(rows,9),ma=[];rows.forEach((r,i)=>ma.push(avg36(rows,i,20)));
 rows.forEach((r,i)=>{const xx=x(i),up=r.close>=r.open,cls=up?'v36-candle-up':'v36-candle-down',vcls=up?'v36-volume-up':'v36-volume-down',yo=y(r.open),yc=y(r.close),yh=y(r.high),yl=y(r.low),top=Math.min(yo,yc),bh=Math.max(1.25,Math.abs(yc-yo));s+=`<line class="${cls}" x1="${xx}" x2="${xx}" y1="${yh}" y2="${yl}"/><rect class="${cls}" x="${xx-candleW/2}" y="${top}" width="${candleW}" height="${bh}" rx=".6"/><rect class="${vcls}" x="${xx-candleW/2}" y="${volY(r.vol)}" width="${candleW}" height="${H-B-volY(r.vol)}"/>`});
 const line=(arr,cls)=>{let d='';arr.forEach((v,i)=>{if(v==null)return;d+=`${d?' L':'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`});return `<path class="${cls}" d="${d}"/>`};s+=line(ma,'v36-ma')+line(ema,'v36-ema');const lastY=y(rows.at(-1).close);s+=`<line class="v36-last" x1="${L}" x2="${W-R}" y1="${lastY}" y2="${lastY}"/><text class="v36-axis-label" x="${L}" y="${H-B+12}">VOLUME</text><text class="v36-axis-label" x="${W-R+8}" y="${H-B+12}">PRICE</text><line class="v36-cross" id="v36CrossX" x1="${L}" x2="${L}" y1="${T}" y2="${H-B}"/><line class="v36-cross" id="v36CrossY" x1="${L}" x2="${W-R}" y1="${T}" y2="${T}"/></svg>`;return{svg:s,rows,min,max,W,H,L,R,T,B,VH,plotH,plotW,lastY}}
function renderOrderChart36(){const box=$('#page-orders .v33-chartbox');if(!box)return;const ticker=currentTicker36(),range=orderRange36(),price=currentPrice36(),currency=currentCurrency36(),key=`${ticker}-${range}-${price}`;if(box.dataset.v36Key===key)return;box.dataset.v36Key=key;const c=tvChartSvg36(ticker,range,price,currency),lastRow=c.rows.at(-1),prev=c.rows.at(-2),change=(lastRow.close-prev.close),pct=change/prev.close*100;box.innerHTML=`<div class="v36-tv-shell"><div class="v36-tv-toolbar"><button class="v36-tv-tool active">Candles</button><button class="v36-tv-tool">Indicators</button><button class="v36-tv-tool">Compare</button><span class="v36-tv-divider"></span><button class="v36-tv-tool">Alert</button><button class="v36-tv-tool">Replay</button><span class="v36-tv-divider"></span><button class="v36-tv-tool">Log</button><button class="v36-tv-tool">Auto</button></div><div class="v36-tv-ohlc"><strong>${esc(ticker)}</strong><span>O <b>${lastRow.open.toFixed(currency==='USD'?2:1)}</b></span><span>H <b>${lastRow.high.toFixed(currency==='USD'?2:1)}</b></span><span>L <b>${lastRow.low.toFixed(currency==='USD'?2:1)}</b></span><span>C <b>${lastRow.close.toFixed(currency==='USD'?2:1)}</b></span><span class="${change>=0?'v36-tv-up':'v36-tv-down'}">${change>=0?'+':''}${change.toFixed(2)} (${pct>=0?'+':''}${pct.toFixed(2)}%)</span><span>Vol <b>${Math.round(lastRow.vol/1000)}K</b></span></div><div class="v36-tv-stage">${c.svg}<div class="v36-tv-legend"><span><i></i>MA 20</span><span><i class="ema"></i>EMA 9</span><span><i class="volume"></i>Volume</span></div><div class="v36-tv-price-label" style="top:${(c.lastY/c.H*100).toFixed(2)}%">${currency} ${lastRow.close.toFixed(currency==='USD'?2:1)}</div><div class="v36-tv-time-label" id="v36TimeLabel">—</div></div></div>`;
 const stage=$('.v36-tv-stage',box),svg=$('svg',stage),cx=$('#v36CrossX',stage),cy=$('#v36CrossY',stage),time=$('#v36TimeLabel',stage);if(stage&&svg&&cx&&cy){stage.addEventListener('mousemove',e=>{const r=stage.getBoundingClientRect(),px=Math.max(0,Math.min(r.width,e.clientX-r.left)),py=Math.max(0,Math.min(r.height,e.clientY-r.top)),vx=px/r.width*c.W,vy=py/r.height*c.H;cx.setAttribute('x1',vx);cx.setAttribute('x2',vx);cy.setAttribute('y1',vy);cy.setAttribute('y2',vy);time.style.left=`${px}px`;const idx=Math.max(0,Math.min(c.rows.length-1,Math.floor((vx-c.L)/c.plotW*c.rows.length)));time.textContent=`${range} · bar ${idx+1}`});}
 $$('.v36-tv-tool',box).forEach(btn=>btn.onclick=()=>{if(btn.textContent==='Indicators')toast('Indicators','MA 20 and EMA 9 are active. Production can add RSI, MACD, VWAP and approved custom studies.');else if(btn.textContent==='Compare')toast('Compare','Add an approved benchmark, peer or second security to the chart.');else if(btn.textContent==='Alert')toast('Price alert','Alert builder opened for price, volume, spread and mandate conditions.');else if(btn.textContent==='Replay')toast('Market replay','Historical execution replay would use timestamped licensed market data.');});}
function issuerLogoData36(ticker){const brand=issuerBrand[ticker]||ticker,h=hash(ticker),bgs=['#0f2b4d','#153e75','#2a3d66','#182c4c','#30465f','#263a52','#2f4858','#1f3c5b'],bg=bgs[h%bgs.length],font=brand.length>16?5.6:brand.length>12?6.4:brand.length>8?7.2:8.2,safe=brand.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),symbol=h%4===0?'<circle cx="14" cy="14" r="7.3" fill="none" stroke="#fff" stroke-width="2"/><path d="M10 14h8M14 10v8" stroke="#fff" stroke-width="1.8"/>':h%4===1?'<path d="M7 19L14 7l7 12z" fill="none" stroke="#fff" stroke-width="2"/><circle cx="14" cy="15" r="2.2" fill="#fff"/>':h%4===2?'<rect x="7" y="7" width="14" height="14" rx="4" fill="none" stroke="#fff" stroke-width="2"/><path d="M10 17l4-6 4 6" fill="none" stroke="#fff" stroke-width="1.8"/>':'<path d="M7 15c3-7 11-7 14 0-3 7-11 7-14 0z" fill="none" stroke="#fff" stroke-width="2"/><circle cx="14" cy="15" r="2.4" fill="#fff"/>';const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="92" height="44" viewBox="0 0 92 44"><rect width="92" height="44" rx="10" fill="#fff"/><rect x="2" y="2" width="88" height="40" rx="9" fill="${bg}"/>${symbol}<text x="28" y="24" font-family="Arial,Helvetica,sans-serif" font-size="${font}" font-weight="700" fill="#fff" dominant-baseline="middle">${safe}</text></svg>`;return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)}
function decorateIssuerLogos36(){const list=$('#page-orders #v33InstrumentList');if(!list)return;$$('.v33-instrument',list).forEach(row=>{const ticker=(row.querySelector('strong')?.textContent||'').trim().replace(/\.(ZW|VX)$/,'');if(!ticker)return;let img=row.querySelector('.v36-issuer-logo');if(!img){img=document.createElement('img');img.className='v36-issuer-logo';img.alt=`${issuerBrand[ticker]||ticker} logo`;row.insertBefore(img,row.firstChild)}if(img.dataset.ticker!==ticker){img.dataset.ticker=ticker;img.src=issuerLogoData36(ticker)}const b=row.querySelector('b');if(b)b.style.display='none'});}
