function rQueue(){const h=$('#v36ReconQueue');if(!h)return;const a=rFiltered();if(!a.some(x=>x.id===rSelected))rSelected=a[0]?.id||'';h.innerHTML=a.length?a.map(r=>`<div class="v36-recon-item ${r.id===rSelected?'active':''} ${r.severity==='Critical'?'critical':''} ${r.status==='matched'?'matched':''} ${r.status==='waiting'?'waiting':''}" data-rid="${r.id}"><i></i><span><strong>${esc(r.family)} · ${esc(r.title)}</strong><small>${esc(r.id)} · ${esc(r.owner)} · age ${esc(r.age)}</small><small>Next: ${esc(r.next)}</small></span><em>${esc(r.diff)}<small>${esc(r.deadline)}</small></em></div>`).join(''):'<div style="padding:24px;text-align:center;color:#75849a;font-size:10px">No records in this view.</div>';$$('[data-rid]',h).forEach(x=>x.onclick=()=>{rSelected=x.dataset.rid;rQueue();rDetail()})}
function sourceCard36(id,label){const s=rSources[id];return `<section class="v36-evidence"><header><div><div class="v36-kicker">${label}</div><h3>${esc(s.system)}</h3><p>${esc(s.type)} · ${esc(s.object)}</p></div><button class="v36-btn" data-source="${id}" style="height:29px;padding:0 9px">Preview</button></header><dl><dt>Run reference</dt><dd>${esc(s.ref)}</dd><dt>Received</dt><dd>${esc(s.received)}</dd><dt>As-of</dt><dd>${esc(s.asof)}</dd><dt>Population</dt><dd>${esc(s.records)} records</dd><dt>Integrity</dt><dd>${esc(s.integrity)}</dd></dl></section>`}
function previewSource36(id,r){const s=rSources[id];const sample=id==='BANK'?'<tr><td>31 Aug</td><td>Growth Equity IV fee</td><td>−1,460.00</td><td>Value date 31 Aug</td></tr><tr><td>31 Aug</td><td>Subscription receipt</td><td>+240,000.00</td><td>Cleared</td></tr>':id==='BRKA'?'<tr><td>ORD-49217</td><td>INN</td><td>Buy 7,800</td><td>USD 1.13</td></tr><tr><td>ORD-49218</td><td>DLTA</td><td>Buy 14,000</td><td>ZWG 63.50</td></tr>':id==='CUSA'?'<tr><td>Custody 14</td><td>DLTA</td><td>643,500</td><td>Current</td></tr><tr><td>Custody 14</td><td>FBC</td><td>210,000</td><td>Current</td></tr>':'<tr><td>Controlled row</td><td>Source record</td><td>Validated</td><td>Current</td></tr>';modal36({eyebrow:'RECONCILIATION · SOURCE EVIDENCE',title:esc(s.object),subtitle:`${esc(s.system)} · ${esc(s.ref)} · received ${esc(s.received)}`,wide:true,body:`<div class="v35-source-preview"><div class="v35-preview-paper"><div class="v36-kicker">SOURCE PREVIEW · ${esc(s.type)}</div><h3>${esc(s.system)}</h3><p>Linked to ${esc(r.id)} · ${esc(r.title)} · as-of ${esc(s.asof)}</p><table><thead><tr><th>Reference</th><th>Record</th><th>Value / quantity</th><th>State</th></tr></thead><tbody>${sample}</tbody></table><p style="margin-top:18px">Integrity: ${esc(s.integrity)} · immutable source reference retained.</p></div></div>`})}
function rDetail(){const h=$('#v36ReconDetail');if(!h)return;const r=rRows.find(x=>x.id===rSelected);if(!r){h.innerHTML='<div style="padding:34px;text-align:center;color:#75849a;font-size:11px">Choose a reconciliation record.</div>';return}const isMatch=r.status==='matched',isWait=r.status==='waiting',isCheck=r.status==='checker';const actionTitle=isMatch?'No action required':isWait?'Get the missing independent source':isCheck?'Independently review the maker correction':r.next;h.innerHTML=`<div class="v36-detail-head"><div><div class="v36-kicker">${esc(r.id)} · ${esc(r.family)}</div><h2>${esc(r.title)}</h2><p>${esc(r.owner)} · ${esc(r.deadline)}</p></div><span class="v36-chip ${isMatch?'good':r.severity==='Critical'?'fail':isWait?'warn':''}">${esc(r.status==='action'?r.severity:r.status==='checker'?'Ready for checker':r.status==='waiting'?'Waiting source':'Matched')}</span></div><div class="v36-next-action"><b>${isMatch?'✓':isWait?'!':isCheck?'C':'→'}</b><span><span>What should happen next</span><strong>${esc(actionTitle)}</strong><small>${isMatch?'Match rule and evidence remain available for audit and replay.':isWait?'Do not manufacture a break while the required external file is late.':isCheck?'Checker must be independent from the maker and verify evidence before closure.':'The maker should resolve the underlying source or controlled book — never force the match.'}</small></span>${isMatch?'':`<button class="v36-btn primary" id="v36PrimaryAction">${isWait?'Escalate source':isCheck?'Review as checker':'Start resolution'}</button>`}</div><div class="v36-detail-tabs"><button class="${rTab==='compare'?'active':''}" data-rtab="compare">Compare & evidence</button><button class="${rTab==='rules'?'active':''}" data-rtab="rules">Match logic</button><button class="${rTab==='resolve'?'active':''}" data-rtab="resolve">Resolve & approve</button><button class="${rTab==='audit'?'active':''}" data-rtab="audit">History</button></div><div class="v36-detail-body" id="v36ReconPane"></div>`;$$('[data-rtab]',h).forEach(b=>b.onclick=()=>{rTab=b.dataset.rtab;rDetail()});$('#v36PrimaryAction',h)?.addEventListener('click',()=>{rTab=isWait?'compare':'resolve';rDetail()});rPane(r)}
function rPane(r){const h=$('#v36ReconPane');if(!h)return;const good=r.status==='matched';if(rTab==='compare'){h.innerHTML=`<div class="v36-compare"><div class="v36-record"><span>Internal authoritative record</span><strong>${esc(r.internal)}</strong><small>${esc(rSources[r.left].system)} · ${esc(rSources[r.left].ref)}</small></div><div class="v36-delta ${good?'good':''}"><span>Difference</span><strong>${esc(r.diff)}</strong><small>${good?'100% match':r.status==='waiting'?'awaiting source':'candidate match available'}</small></div><div class="v36-record"><span>Independent evidence</span><strong>${esc(r.external)}</strong><small>${esc(rSources[r.right].system)} · ${esc(rSources[r.right].ref)}</small></div></div><div class="v36-evidence-grid">${sourceCard36(r.left,'INTERNAL SOURCE')}${sourceCard36(r.right,'INDEPENDENT SOURCE')}</div>${good?'<div style="margin-top:10px;padding:10px;border:1px solid #b8e1d5;background:#f4fbf8;border-radius:9px;font-size:10px;color:#41685d"><strong>Matched automatically.</strong> This record is out of the human work queue, but the source objects and matching rule remain retained.</div>':r.status==='waiting'?'<div style="margin-top:10px;padding:10px;border:1px solid #f0d19d;background:#fff8ec;border-radius:9px;font-size:10px;color:#735b32"><strong>Source acquisition control.</strong> The external file is late. Escalate the source owner; do not treat missing evidence as a financial difference.</div>':`<div class="v36-resolution"><section class="v36-action-list"><h3>Investigation starter</h3><div class="v36-action-step"><b>1</b><span><strong>Review suggested candidate</strong><small>${esc(r.candidate)}</small></span></div><div class="v36-action-step"><b>2</b><span><strong>Confirm or override root cause</strong><small>${esc(r.cause)}</small></span></div><div class="v36-action-step"><b>3</b><span><strong>Correct the source / controlled book</strong><small>${esc(r.next)}</small></span></div><div class="v36-action-step"><b>4</b><span><strong>Re-run matching</strong><small>Exception closes only if the records agree or an approved tolerance applies.</small></span></div></section><aside class="v36-resolution-form"><h3>Fast actions</h3><button class="v36-btn" id="v36AcceptCandidate" style="width:100%;margin-bottom:6px">Accept candidate</button><button class="v36-btn" id="v36QuerySource" style="width:100%;margin-bottom:6px">Query counterparty / source</button><button class="v36-btn" id="v36AttachEvidence" style="width:100%">Attach supporting evidence</button></aside></div>`}`;$$('[data-source]',h).forEach(b=>b.onclick=()=>previewSource36(b.dataset.source,r));$('#v36AcceptCandidate',h)?.addEventListener('click',()=>toast('Candidate linked',`${r.candidate} added to the investigation record. Maker judgement is still required.`));$('#v36QuerySource',h)?.addEventListener('click',()=>toast('Source query prepared',`Controlled query for ${rSources[r.right].system} created with reconciliation context and evidence references.`));$('#v36AttachEvidence',h)?.addEventListener('click',()=>toast('Evidence attachment','Upload/attach flow opened for supporting document, email, broker note or source-system evidence.'))}
 else if(rTab==='rules'){h.innerHTML=`<div class="v36-card"><div class="v36-card-head"><div><div class="v36-kicker">MATCH LOGIC</div><h2>Why the engine linked these records</h2><p>Exact keys are evaluated before weighted/candidate logic; failed material fields remain exceptions.</p></div><span class="v36-chip">Rule set REC-${esc(r.family.toUpperCase().replace(/\W/g,''))}-06</span></div><div class="v36-card-body">${r.rules.map(x=>`<div style="display:grid;grid-template-columns:minmax(0,1fr) auto;gap:9px;padding:9px 0;border-bottom:1px solid #edf1f5"><span><strong style="font-size:10px">${esc(x[0])}</strong><small style="display:block;font-size:9px;color:#78879a;margin-top:2px">${esc(x[2])}</small></span><em style="font-size:9px;font-style:normal;font-weight:850">${esc(x[1])}</em></div>`).join('')}</div></div>`}
 else if(rTab==='resolve'){h.innerHTML=r.status==='matched'?'<div style="padding:20px;text-align:center;color:#5e6f83;font-size:10px">This record is already matched and requires no human resolution.</div>':r.status==='waiting'?`<div class="v36-action-list"><h3>Late source playbook</h3><div class="v36-action-step"><b>1</b><span><strong>Confirm expected delivery</strong><small>${esc(rSources[r.right].system)} · ${esc(rSources[r.right].object)}</small></span></div><div class="v36-action-step"><b>2</b><span><strong>Escalate source owner</strong><small>Retain timestamp and escalation evidence.</small></span></div><div class="v36-action-step"><b>3</b><span><strong>Use alternate source only if authorised</strong><small>Alternate evidence must be approved and traceable.</small></span></div><button class="v36-btn primary" id="v36EscSource" style="margin-top:9px">Escalate late source</button></div>`:`<div class="v36-resolution"><section class="v36-action-list"><h3>${r.status==='checker'?'Checker evidence':'Maker resolution steps'}</h3><div class="v36-action-step"><b>1</b><span><strong>Root cause</strong><small>${esc(r.cause)}</small></span></div><div class="v36-action-step"><b>2</b><span><strong>Corrective action</strong><small>${esc(r.next)}</small></span></div><div class="v36-action-step"><b>3</b><span><strong>Evidence</strong><small>Internal + independent source objects must remain linked.</small></span></div><div class="v36-action-step"><b>4</b><span><strong>Re-match</strong><small>Checker can close only after successful rematch.</small></span></div></section><aside class="v36-resolution-form"><h3>${r.status==='checker'?'Independent checker':'Submit maker resolution'}</h3><label>Root cause<select id="v36Cause"><option>${esc(r.cause)}</option><option>Timing difference</option><option>Internal booking error</option><option>External source error</option><option>Reference-data mismatch</option></select></label><label>Resolution rationale<textarea id="v36Rationale" placeholder="Explain the evidence, correction and expected rematch result."></textarea></label><button class="v36-btn primary" id="v36SubmitResolution" style="width:100%">${r.status==='checker'?'Approve checker close':'Submit maker resolution'}</button><div class="v36-proof-row"><small>Maker: ${esc(r.maker)}<br>Checker: ${esc(r.checker)}</small><span class="v36-chip ${r.status==='checker'?'warn':''}">${r.status==='checker'?'Pending checker':'Maker stage'}</span></div></aside></div>`;$('#v36EscSource',h)?.addEventListener('click',()=>toast('Late source escalated',`${rSources[r.right].system} escalation recorded against ${r.id}.`));$('#v36SubmitResolution',h)?.addEventListener('click',()=>{const rationale=$('#v36Rationale',h)?.value.trim();if(!rationale)return toast('Rationale required','Record why the correction is appropriate before submitting.','error');if(r.status==='checker'){r.status='matched';r.checker='Independent Operations · now';r.diff='0';r.external=r.internal;toast('Reconciliation closed',`${r.id} re-matched and was independently approved.`);rMode='matched'}else{r.status='checker';r.maker='Current operator · now';toast('Maker resolution submitted',`${r.id} is ready for independent checker review.`);rMode='checker'}rSelected=r.id;renderRecon36()})}
 else{h.innerHTML=`<div class="v36-audit-list"><div class="v36-audit-event"><time>15:42</time><i></i><span><strong>Independent source received / evaluated</strong><small>${esc(rSources[r.right].system)} · ${esc(rSources[r.right].ref)}</small></span></div><div class="v36-audit-event"><time>15:43</time><i></i><span><strong>Matching rule executed</strong><small>${esc(r.family)} rule set · source provenance frozen.</small></span></div><div class="v36-audit-event"><time>15:44</time><i></i><span><strong>${r.status==='matched'?'Record matched':'Exception created'}</strong><small>${r.status==='matched'?'No manual action required.':`Assigned to ${esc(r.owner)}.`}</small></span></div><div class="v36-audit-event"><time>Now</time><i></i><span><strong>Current control state</strong><small>Maker ${esc(r.maker)} · checker ${esc(r.checker)}</small></span></div></div>`}}
function renderRecon36(){const s=rStats(),k=$('#v36ReconKpis');if(k)k.innerHTML=rKpis();const count=$('#v36QueueCount');if(count)count.textContent=`${rFiltered().length} records`;$$('[data-rmode]').forEach(b=>b.classList.toggle('active',b.dataset.rmode===rMode));rQueue();rDetail();const focus=$('#v36FocusPrimary strong');if(focus)focus.textContent=`${s.material} material exceptions need a human decision before close`}
function buildRecon36(){const p=$('#page-reconciliations');if(!p)return;p.className='page active v33-workspace';p.innerHTML=`<div class="v36-recon-shell"><header class="v36-recon-head"><div><div class="v36-kicker">TODAY'S CONTROL DESK · EVIDENCE → DECISION → CLOSE</div><h1>Reconciliations</h1><p>Start with what needs your attention. Every difference shows the two source records, why the engine linked them, the next human action, and the maker/checker path to closure.</p></div><div class="v36-recon-actions"><button class="v36-btn" id="v36Sources">Source runs</button><button class="v36-btn" id="v36Import">Import source</button><button class="v36-btn primary" id="v36Run">Validate & run matching</button></div></header><div class="v36-focus-strip"><div class="v36-focus-primary" id="v36FocusPrimary"><span>What needs attention now</span><strong>2 material exceptions need a human decision before close</strong><small>Prioritised by materiality, age, close dependency and SLA.</small></div><div class="v36-focus-card" data-focus="REC-66102"><span>Critical</span><strong>US$ 412k settlement fail</strong><small>2.8d · broker + custodian query</small></div><div class="v36-focus-card" data-focus="REC-66118"><span>Cash</span><strong>US$ 1,460 bank difference</strong><small>Confirm charge · journal if valid</small></div><div class="v36-focus-card" data-focus="PEN-1031"><span>Waiting source</span><strong>Custodian B file late</strong><small>Escalate · do not create false break</small></div></div><div class="v36-recon-kpis" id="v36ReconKpis">${rKpis()}</div><section class="v36-run-rail"><div class="v36-run-rail-head"><div><span>31 AUG CLOSE RUN · REC-RUN-20260831-04</span><strong>Control run is at investigation / approval</strong></div><button id="v36RunDetails">Show source-control details</button></div><div class="v36-run-steps">${rRunSteps()}</div><div id="v36SourceDetails" hidden style="margin-top:8px;border-top:1px solid #edf1f5;padding-top:8px;font-size:9.5px;color:#67768a">Internal books frozen at 15:30 CAT · 8/9 external source families current · Custodian B cash source late · control totals passed for all received populations · matching rules effective version REC-RULES-06.</div></section><div class="v36-recon-toolbar"><div class="v36-recon-search"><input id="v36ReconSearch" placeholder="Search account, security, break, source or owner"></div><select id="v36ReconFamily"><option>All</option><option>Cash</option><option>Holdings</option><option>Trades</option><option>Settlement</option><option>Units</option><option>Pricing / NAV</option></select><input type="date" value="2026-08-31" id="v36ReconDate"><button class="v36-btn" id="v36Signoff">Daily sign-off</button></div><div class="v36-recon-layout"><aside class="v36-card"><div class="v36-queue-head"><div class="v36-kicker">MY WORK QUEUE</div><h2>Work the exceptions, not the matches</h2><p id="v36QueueCount">0 records</p></div><div class="v36-queue-tabs"><button class="active" data-rmode="action">Needs action</button><button data-rmode="waiting">Waiting source</button><button data-rmode="checker">Ready checker</button><button data-rmode="matched">Matched</button></div><div class="v36-recon-queue" id="v36ReconQueue"></div></aside><main class="v36-card v36-detail" id="v36ReconDetail"></main></div></div>`;renderRecon36();$$('[data-rmode]',p).forEach(b=>b.onclick=()=>{rMode=b.dataset.rmode;const a=rFiltered();rSelected=a[0]?.id||'';rTab='compare';renderRecon36()});$('#v36ReconSearch',p).oninput=e=>{rQuery=e.target.value.toLowerCase();renderRecon36()};$('#v36ReconFamily',p).onchange=e=>{rFamily=e.target.value;const a=rFiltered();rSelected=a[0]?.id||'';renderRecon36()};$$('[data-focus]',p).forEach(x=>x.onclick=()=>{const r=rRows.find(r=>r.id===x.dataset.focus);if(!r)return;rMode=r.status;rSelected=r.id;rTab='compare';renderRecon36()});$('#v36RunDetails',p).onclick=()=>{const d=$('#v36SourceDetails',p);d.hidden=!d.hidden;$('#v36RunDetails',p).textContent=d.hidden?'Show source-control details':'Hide source-control details'};$('#v36Run',p).onclick=()=>toast('Matching run complete','Received populations passed validation and matching. Late sources remain waiting rather than becoming false exceptions.');$('#v36Sources',p).onclick=()=>modal36({eyebrow:'RECONCILIATION · SOURCE RUNS',title:'Current evidence population',subtitle:'Every match must be reproducible from a retained internal and independent source.',wide:true,body:`<div style="overflow:auto"><table class="v34-report-table"><thead><tr><th>Source</th><th>Object</th><th>Type</th><th>Received</th><th>As-of</th><th>Records</th><th>State</th></tr></thead><tbody>${Object.entries(rSources).map(([id,s])=>`<tr><td><strong>${esc(s.system)}</strong></td><td>${esc(s.object)}</td><td>${esc(s.type)}</td><td>${esc(s.received)}</td><td>${esc(s.asof)}</td><td>${esc(s.records)}</td><td><span class="v36-chip ${s.received==='Late'?'warn':'good'}">${s.received==='Late'?'Late':'Current'}</span></td></tr>`).join('')}</tbody></table></div>`});$('#v36Import',p).onclick=()=>toast('Import source','Controlled upload accepts bank, broker, custodian and transfer-agent files with schema mapping and control totals.');$('#v36ReconDate',p).onchange=e=>toast('As-of date changed',`A new controlled source population would be selected for ${e.target.value}.`);$('#v36Signoff',p).onclick=()=>modal36({eyebrow:'RECONCILIATION · DAILY SIGN-OFF',title:'Close readiness: conditional',subtitle:'Resolve material exceptions and the late required source before the independent checker can sign off.',body:'<div class="v35-checklist"><div class="v35-checkitem"><b>✓</b><span><strong>Internal books frozen</strong><small>IBOR / OMS / ABOR</small></span></div><div class="v35-checkitem"><b>!</b><span><strong>External source complete</strong><small>Custodian B file late</small></span></div><div class="v35-checkitem"><b>!</b><span><strong>Material exceptions</strong><small>Settlement and cash items open</small></span></div><div class="v35-checkitem"><b>✓</b><span><strong>Segregation of duties</strong><small>Independent checker assigned</small></span></div></div>'})}

