function workloadSvg36(){const hrs=['09','10','11','12','13','14','15','16','17','18'],due=[3,4,4,5,5,7,8,9,5,2],done=[1,2,3,4,5,6,6,7,8,9],block=[0,0,0,1,1,1,2,2,2,1],W=760,H=245,L=42,R=18,T=18,B=38,max=10,x=i=>L+(W-L-R)*i/(hrs.length-1),y=v=>T+(H-T-B)*(1-v/max),path=a=>a.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Operations workload by hour">`;for(let i=0;i<=5;i++){const v=i*2,yy=y(v);s+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text x="${L-7}" y="${yy+3}" text-anchor="end">${v}</text>`}hrs.forEach((h,i)=>s+=`<text x="${x(i)}" y="${H-15}" text-anchor="middle">${h}:00</text>`);s+=`<text class="v36-axis-label" x="12" y="${H/2}" text-anchor="middle" transform="rotate(-90 12 ${H/2})">TASK COUNT</text><text class="v36-axis-label" x="${W/2}" y="${H-1}" text-anchor="middle">OPERATING HOUR</text><path class="series-due" d="${path(due)}"/><path class="series-done" d="${path(done)}"/><path class="series-block" d="${path(block)}"/>`;due.forEach((v,i)=>s+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.5" fill="#3158e8"/>`);done.forEach((v,i)=>s+=`<circle cx="${x(i)}" cy="${y(v)}" r="2.5" fill="#0a9474"/>`);s+='</svg>';return s}
function cashDeadlineSvg36(){const labels=['Capital call','Broker settle','Distribution','Fees'],inn=[0,.62,.44,0],out=[1.10,.84,0,.18],W=510,H=245,L=48,R=18,T=20,B=48,max=1.2,group=(W-L-R)/labels.length,y=v=>T+(H-T-B)*(1-v/max);let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cash movement by operational deadline">`;for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);s+=`<line class="grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text x="${L-7}" y="${yy+3}" text-anchor="end">${v.toFixed(1)}m</text>`}labels.forEach((lab,i)=>{const x=L+group*(i+.5),bw=24;s+=`<rect class="bar-in" x="${x-bw-2}" y="${y(inn[i])}" width="${bw}" height="${H-B-y(inn[i])}" rx="3"/><rect class="bar-out" x="${x+2}" y="${y(out[i])}" width="${bw}" height="${H-B-y(out[i])}" rx="3"/><text x="${x}" y="${H-19}" text-anchor="middle">${lab}</text>`});s+=`<text class="v36-axis-label" x="12" y="${H/2}" text-anchor="middle" transform="rotate(-90 12 ${H/2})">CASH MOVEMENT · US$ m</text><text class="v36-axis-label" x="${W/2}" y="${H-2}" text-anchor="middle">DEADLINE / EVENT</text></svg>`;return s}
function renderOpsTasks36(){const h=$('#v36OpsRunbook');if(!h)return;const a=opsTasks36.filter(t=>opsFilter36==='All'||t[3]===opsFilter36);h.innerHTML=a.map((t,i)=>`<div class="v36-ops-task ${t[3].toLowerCase()}" data-oid="${i}"><time>${t[0]}</time><i></i><span><strong>${esc(t[1])} · ${esc(t[2])}</strong><small>${esc(t[4])} · owner ${esc(t[5])}</small></span><em>${esc(t[3])}</em></div>`).join('');$$('[data-oid]',h).forEach(x=>x.onclick=()=>{const t=a[+x.dataset.oid];modal36({eyebrow:`OPERATIONS · ${esc(t[1])}`,title:esc(t[2]),subtitle:`${esc(t[0])} · ${esc(t[3])} · owner ${esc(t[5])}`,body:`<div class="v35-list"><div class="v35-row"><span><strong>Dependency</strong><small>What must be true before this task can close</small></span><em>${esc(t[4])}</em></div><div class="v35-row"><span><strong>Evidence</strong><small>Source records and approvals retained with the task</small></span><em>Controlled</em></div><div class="v35-row"><span><strong>Hand-off</strong><small>Downstream owner receives state, not an email-only instruction</small></span><em>Tracked</em></div></div>`})})}
function buildOperations36(){const p=$('#page-operations');if(!p)return;p.className='page v33-workspace';p.innerHTML=`<div class="v36-ops-shell"><header class="v36-ops-head"><div><div class="v36-kicker">TODAY'S OPERATING DAY · DEADLINES · DEPENDENCIES · HAND-OFFS</div><h1>Operations Control</h1><p>A responsive control tower for settlement, cash, corporate actions, valuation and close. Work is ordered by deadline and dependency, with reconciliations kept as an independent control function.</p></div><div class="v36-ops-actions"><button class="v36-btn" id="v36OpsCalendar">Calendar</button><button class="v36-btn" id="v36OpsExport">Export runbook</button><button class="v36-btn primary" id="v36OpsNew">+ Operations task</button></div></header><div class="v36-ops-kpis"><div class="v36-ops-kpi"><span>Due today</span><strong>12</strong><small>4 require human action</small></div><div class="v36-ops-kpi"><span>Settlement exposure</span><strong>US$ 842k</strong><small>2 unsettled instructions</small></div><div class="v36-ops-kpi"><span>Cash deadlines</span><strong>3</strong><small>US$ 1.6m gross flows</small></div><div class="v36-ops-kpi"><span>Corporate actions</span><strong>5</strong><small>2 elections due</small></div><div class="v36-ops-kpi"><span>Close blockers</span><strong>2</strong><small>Recon + price evidence</small></div><div class="v36-ops-kpi"><span>Service health</span><strong>99.96%</strong><small>Critical services live</small></div></div><div class="v36-ops-grid"><article class="v36-card"><div class="v36-card-head"><div><div class="v36-kicker">TODAY'S RUNBOOK</div><h2>What the team needs to do next</h2><p>Time-ordered tasks with dependency, accountable owner and state.</p></div><div class="v36-runbook-tools"><button class="active" data-ofilter="All">All</button><button data-ofilter="Due">Due</button><button data-ofilter="Blocked">Blocked</button><button data-ofilter="Scheduled">Scheduled</button></div></div><div class="v36-ops-runbook" id="v36OpsRunbook"></div></article><aside class="v36-card"><div class="v36-card-head"><div><div class="v36-kicker">CLOSE DEPENDENCIES</div><h2>What can stop the day from closing</h2><p>Readiness is derived from the owning control process.</p></div></div><div class="v36-card-body"><div class="v36-dependencies"><div class="v36-dependency" data-go="reconciliations"><span>Settlement</span><strong>94% ready</strong><small>2 breaks in Reconciliations</small><div class="bar"><i style="width:94%"></i></div></div><div class="v36-dependency" data-go="cash"><span>Cash</span><strong>100% current</strong><small>Bank feeds through 15:42</small><div class="bar"><i style="width:100%"></i></div></div><div class="v36-dependency" data-go="valuation"><span>Valuation</span><strong>72% ready</strong><small>1 private price exception</small><div class="bar"><i style="width:72%"></i></div></div><div class="v36-dependency" data-go="accounting"><span>Accounting</span><strong>58% ready</strong><small>Waiting NAV release</small><div class="bar"><i style="width:58%"></i></div></div></div></div><div class="v36-ops-link-list"><div class="v36-ops-link" data-go="reconciliations"><span><strong>Open Reconciliations</strong><small>Work genuine external-book differences</small></span><em>6 open →</em></div><div class="v36-ops-link" data-go="valuation"><span><strong>Open NAV & Valuation</strong><small>Resolve pricing and release NAV</small></span><em>1 blocker →</em></div><div class="v36-ops-link" data-go="corporate-actions"><span><strong>Corporate Actions</strong><small>Complete elections and entitlements</small></span><em>2 due →</em></div></div></aside></div><div class="v36-chart-grid"><section class="v36-chart-card"><div class="v36-chart-head"><div><div class="v36-kicker">WORKLOAD PROFILE</div><h2>Operating workload by hour</h2><p>Labels show operating hour; vertical axis is task count.</p></div><span class="v36-chip">Today · CAT</span></div><div class="v36-chart-stage">${workloadSvg36()}</div><div class="v36-chart-legend"><span><i></i>Due / active tasks</span><span><i class="done"></i>Completed cumulative</span><span><i class="block"></i>Blocked tasks</span></div></section><section class="v36-chart-card"><div class="v36-chart-head"><div><div class="v36-kicker">CASH DEADLINES</div><h2>Cash movement by event</h2><p>Indicative operational inflows and outflows due today.</p></div><span class="v36-chip">US$ m</span></div><div class="v36-chart-stage">${cashDeadlineSvg36()}</div><div class="v36-chart-legend"><span><i class="in"></i>Inflows</span><span><i class="out"></i>Outflows</span></div></section></div></div>`;renderOpsTasks36();$$('[data-ofilter]',p).forEach(b=>b.onclick=()=>{opsFilter36=b.dataset.ofilter;$$('[data-ofilter]',p).forEach(x=>x.classList.toggle('active',x===b));renderOpsTasks36()});$$('[data-go]',p).forEach(x=>x.onclick=()=>go(x.dataset.go));$('#v36OpsCalendar',p).onclick=()=>toast('Operations calendar','Daily, month-end, quarter-end and event-driven deadlines are available with accountable owners.');$('#v36OpsExport',p).onclick=()=>toast('Runbook exported','Current operating-day tasks and dependencies prepared for controlled export.');$('#v36OpsNew',p).onclick=()=>{opsTasks36.unshift(['Now','Manual','New controlled operations task','Due','Manual dependency review','Current operator']);renderOpsTasks36();toast('Operations task created','New task added to today’s runbook.')}}

